import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import { eq } from "drizzle-orm";
import { getDb, subscriptions, organizations } from "@/server/db";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as billing from "@/server/services/billing-service";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { createComment } from "@/server/services/comment-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("follows subscription", async () => {
  const t = await createTenant("sanity-a", "free");
  getDb().update(subscriptions).set({ plan: "growth" }).where(eq(subscriptions.orgId, t.org.id)).run();
  expect((await orgRepo.findOrgById(t.org.id))!.plan).toBe("growth");
  expect((await orgRepo.listOrgsForUser(t.org.ownerId))[0].plan).toBe("growth");
  const b = await createTenant("sanity-b", "growth");
  await billing.changePlan(b.actors.owner!, { orgId: b.org.id, plan: "starter", interval: "monthly" } as never);
  expect((await orgRepo.findOrgById(b.org.id))!.plan).toBe("starter");
  const raw = getDb().select().from(organizations).where(eq(organizations.id, b.org.id)).get();
  expect(raw!.plan).toBe("starter");
  const c = await createTenant("sanity-c", "growth");
  const future = new Date(Date.now() + 30 * 86400000);
  const r1 = await runTrialExpiryJob(future);
  expect((await orgRepo.findOrgById(c.org.id))!.plan).toBe("free");
  expect((await orgRepo.findOrgById(b.org.id))!.plan).toBe("starter");
  const r2 = await runTrialExpiryJob(future);
  console.log(r1, r2);
});
EOF
npx vitest run tests/zz-tmp-sanity.test.ts 2>&1 | grep -v "npm warn" | tail -30; rm tests/zz-tmp-sanity.test.ts

